class SnapshotArrayBrute {
    int[] arr;
    List<int[]> snapshots = new ArrayList<>();

    SnapshotArrayBrute(int length) {
        arr = new int[length];
    }

    void set(int index, int val) {
        arr[index] = val;
    }

    int snap() {
        snapshots.add(arr.clone());                    // copy the ENTIRE array
        return snapshots.size() - 1;
    }

    int get(int index, int snapId) {
        return snapshots.get(snapId)[index];
    }
}

