class SnapshotArray:
    def __init__(self, length):
        self.snap_id = 0
        self.history = [[(0, 0)] for _ in range(length)]   # per-index list of (snapId, value)

    def set(self, index, val):
        h = self.history[index]
        if h[-1][0] == self.snap_id:
            h[-1] = (self.snap_id, val)                       # overwrite the pending entry
        else:
            h.append((self.snap_id, val))

    def snap(self):
        self.snap_id += 1
        return self.snap_id - 1

    def get(self, index, snap_id):
        h = self.history[index]
        lo, hi, ans = 0, len(h) - 1, 0
        while lo <= hi:
            mid = (lo + hi) // 2
            if h[mid][0] <= snap_id:                            # binary search for last <= snap_id
                ans = h[mid][1]
                lo = mid + 1
            else:
                hi = mid - 1
        return ans

