import java.util.*;

class SnapshotArray {
    int snapId = 0;
    List<List<int[]>> history = new ArrayList<>();          // per-index list of [snapId, value]

    SnapshotArray(int length) {
        for (int i = 0; i < length; i++) {
            List<int[]> h = new ArrayList<>();
            h.add(new int[]{0, 0});
            history.add(h);
        }
    }

    void set(int index, int val) {
        List<int[]> h = history.get(index);
        int[] last = h.get(h.size() - 1);
        if (last[0] == snapId) last[1] = val;                    // overwrite the pending entry
        else h.add(new int[]{snapId, val});
    }

    int snap() {
        return snapId++;
    }

    int get(int index, int snapIdQuery) {
        List<int[]> h = history.get(index);
        int lo = 0, hi = h.size() - 1, ans = 0;
        while (lo <= hi) {
            int mid = (lo + hi) / 2;
            if (h.get(mid)[0] <= snapIdQuery) {                   // binary search for last <= query
                ans = h.get(mid)[1];
                lo = mid + 1;
            } else hi = mid - 1;
        }
        return ans;
    }
}

