#include <bits/stdc++.h>
using namespace std;

class SnapshotArray {
public:
    int snapId = 0;
    vector<vector<pair<int,int>>> history;                     // per-index list of (snapId, value)

    SnapshotArray(int length) : history(length, vector<pair<int,int>>{{0, 0}}) {}

    void set(int index, int val) {
        auto& h = history[index];
        if (h.back().first == snapId) h.back().second = val;      // overwrite the pending entry
        else h.push_back({snapId, val});
    }

    int snap() {
        return snapId++;
    }

    int get(int index, int snapIdQuery) {
        auto& h = history[index];
        int lo = 0, hi = h.size() - 1, ans = 0;
        while (lo <= hi) {
            int mid = (lo + hi) / 2;
            if (h[mid].first <= snapIdQuery) {                     // binary search for last <= query
                ans = h[mid].second;
                lo = mid + 1;
            } else hi = mid - 1;
        }
        return ans;
    }
};
